/**
 * Unit tests for lib/session-staleness (CC 2.1.251 payload readers, #3789).
 * The resume fixture is the SessionStart payload captured on 2.1.251 on
 * 2026-08-29 (paths elided); the startup fixture is the same session's first
 * event, which carries none of the staleness fields.
 */

import { describe, test, expect } from 'vitest';
import {
  readResumeStaleness,
  readModelSwitch,
  isPremiumTierModel,
  WARM_RESUME_MAX_IDLE_SECONDS,
} from '../../lib/session-staleness.js';
import type { HookInput } from '../../types.js';

const resume = {
  session_id: 'fb584022-5d13-4efb-9356-70ff9058f78b',
  transcript_path: '/tmp/t.jsonl',
  cwd: '/tmp/hookdump',
  hook_event_name: 'SessionStart',
  source: 'resume',
  session_title: 'hookdump',
  seconds_since_last_response: 6,
  context_tokens: 123705,
  prompt_cache_likely_expired: false,
  estimated_cache_write_usd: 0.4948,
} as unknown as HookInput;

const startup = {
  session_id: 'fb584022-5d13-4efb-9356-70ff9058f78b',
  transcript_path: '/tmp/t.jsonl',
  cwd: '/tmp/hookdump',
  hook_event_name: 'SessionStart',
  source: 'startup',
} as unknown as HookInput;

describe('readResumeStaleness', () => {
  test('reads the measured 2.1.251 resume fields', () => {
    const s = readResumeStaleness(resume);
    expect(s).toMatchObject({
      isResume: true,
      secondsSinceLastResponse: 6,
      contextTokens: 123705,
      promptCacheLikelyExpired: false,
      estimatedCacheWriteUsd: 0.4948,
      sessionTitle: 'hookdump',
      isWarmRecentResume: true,
    });
  });

  test('a startup payload is neutral on every field', () => {
    const s = readResumeStaleness(startup);
    expect(s.isResume).toBe(false);
    expect(s.isWarmRecentResume).toBe(false);
    expect(s.secondsSinceLastResponse).toBe(0);
    expect(s.contextTokens).toBe(0);
    expect(s.estimatedCacheWriteUsd).toBe(0);
  });

  test('an expired cache is never a warm resume', () => {
    const s = readResumeStaleness({ ...(resume as object), prompt_cache_likely_expired: true } as unknown as HookInput);
    expect(s.promptCacheLikelyExpired).toBe(true);
    expect(s.isWarmRecentResume).toBe(false);
  });

  test('a resume past the idle window is not recent even with a warm cache', () => {
    const s = readResumeStaleness({ ...(resume as object), seconds_since_last_response: WARM_RESUME_MAX_IDLE_SECONDS + 1 } as unknown as HookInput);
    expect(s.isWarmRecentResume).toBe(false);
  });

  test('a resume on a CC that omits the fields is unknown, not recent', () => {
    const s = readResumeStaleness({ hook_event_name: 'SessionStart', source: 'resume' } as unknown as HookInput);
    expect(s.isResume).toBe(true);
    expect(s.isWarmRecentResume).toBe(false);
  });

  test('malformed values read as neutral instead of throwing', () => {
    const s = readResumeStaleness({ source: 'resume', seconds_since_last_response: 'soon', context_tokens: null, estimated_cache_write_usd: NaN, session_title: 7 } as unknown as HookInput);
    expect(s.secondsSinceLastResponse).toBe(0);
    expect(s.contextTokens).toBe(0);
    expect(s.estimatedCacheWriteUsd).toBe(0);
    expect(s.sessionTitle).toBe('');
  });
});

describe('readModelSwitch', () => {
  test('reads the measured 2.1.251 model-switch fields', () => {
    const sw = readModelSwitch({
      hook_event_name: 'PreModelSwitch', from_model: 'claude-sonnet-5', to_model: 'claude-opus-5',
      requested_model: 'claude-opus-5', source: 'command', context_tokens: 0, prompt_cache_warm: false,
      cache_ttl: '1h', estimated_cache_write_usd: 0, pricing: 'catalog',
    } as unknown as HookInput);
    expect(sw).toEqual({
      fromModel: 'claude-sonnet-5', toModel: 'claude-opus-5', requestedModel: 'claude-opus-5', source: 'command',
      contextTokens: 0, promptCacheWarm: false, cacheTtl: '1h', estimatedCacheWriteUsd: 0, pricing: 'catalog',
    });
  });

  test('requested_model falls back to to_model', () => {
    expect(readModelSwitch({ to_model: 'x' } as unknown as HookInput).requestedModel).toBe('x');
  });
});

describe('isPremiumTierModel', () => {
  test.each(['fable', 'claude-fable-5', 'claude-fable-5[1m]', 'mythos', 'claude-mythos-5', 'CLAUDE-FABLE-5'])('%s is premium', (m) => {
    expect(isPremiumTierModel(m)).toBe(true);
  });
  test.each(['opus', 'claude-opus-5', 'sonnet', 'claude-sonnet-5', 'haiku', 'inherit', ''])('%s is not', (m) => {
    expect(isPremiumTierModel(m)).toBe(false);
  });
});
